-- 独立的视频动作配置；保留自拍、已有视频任务和其实际提示词快照。
UPDATE productConfiguration SET draft = JSON_SET(draft, '$.videos', COALESCE(JSON_EXTRACT(draft, '$.videos'), CAST('{"presets":[{"id":"wave","label":{"zh-CN":"招手","en":"Wave","ja":"手を振る","ko":"손 흔들기"},"emoji":"👋","minLevel":1,"promptFragment":"The character raises one hand and waves gently toward the camera two or three times, smiling naturally, then lowers the hand. One continuous shot, smooth natural movement.","enabled":true},{"id":"heart","label":{"zh-CN":"比心","en":"Hand heart","ja":"ハートポーズ","ko":"손하트"},"emoji":"🫶","minLevel":2,"promptFragment":"The character brings both hands together at chest level to form a heart, holds it briefly with a warm smile, then relaxes the hands. Smooth continuous movement and consistent identity.","enabled":true},{"id":"turn","label":{"zh-CN":"转身","en":"Turn around","ja":"振り向く","ko":"뒤돌아보기"},"emoji":"💃","minLevel":1,"promptFragment":"The character slowly turns to the side, glances back over one shoulder toward the camera with a gentle smile, then comes to a natural stop. A continuous medium shot with smooth motion.","enabled":true},{"id":"nod","label":{"zh-CN":"点头微笑","en":"Nod and smile","ja":"うなずいて微笑む","ko":"끄덕이며 미소"},"emoji":"😊","minLevel":1,"promptFragment":"The character looks toward the camera, gives a small friendly nod and gradually breaks into a natural smile. Subtle breathing and blinking, a steady continuous shot.","enabled":true},{"id":"blow_kiss","label":{"zh-CN":"飞吻","en":"Blow a kiss","ja":"投げキッス","ko":"손키스"},"emoji":"😘","minLevel":3,"promptFragment":"The character lifts one hand to the lips and gently blows a kiss toward the camera, then lowers the hand with an affectionate smile. Natural facial movement in one continuous shot.","enabled":true},{"id":"twirl","label":{"zh-CN":"轻盈转圈","en":"Gentle twirl","ja":"軽く一回転","ko":"가볍게 돌기"},"emoji":"🌷","minLevel":4,"promptFragment":"The character takes a small step and makes one graceful slow twirl, allowing clothing and hair to follow the movement naturally, then faces the camera again. A stable full-body shot.","enabled":true},{"id":"dance","label":{"zh-CN":"轻快舞动","en":"Playful dance","ja":"軽やかに踊る","ko":"가볍게 춤추기"},"emoji":"🎵","minLevel":4,"promptFragment":"The character performs a short playful dance with two gentle side steps and relaxed arm movements, smiling with the rhythm. Continuous smooth full-body movement, steady framing.","enabled":true},{"id":"walk_together","label":{"zh-CN":"牵手同行","en":"Walk together","ja":"手をつないで歩く","ko":"손잡고 걷기"},"emoji":"🤝","minLevel":6,"promptFragment":"From a first-person viewpoint, the character reaches one hand toward the viewer as if inviting them to hold hands, then starts walking forward and glances back warmly. Gentle continuous tracking movement.","enabled":true},{"id":"good_night","label":{"zh-CN":"晚安挥手","en":"Goodnight wave","ja":"おやすみの手振り","ko":"잘 자 인사"},"emoji":"🌙","minLevel":7,"promptFragment":"In a quiet cozy evening setting, the character gives a small sleepy wave toward the camera, closes the eyes briefly with a soft smile, and relaxes. Gentle breathing and natural continuous movement.","enabled":true}]}' AS JSON))), published = JSON_SET(published, '$.videos', COALESCE(JSON_EXTRACT(published, '$.videos'), CAST('{"presets":[{"id":"wave","label":{"zh-CN":"招手","en":"Wave","ja":"手を振る","ko":"손 흔들기"},"emoji":"👋","minLevel":1,"promptFragment":"The character raises one hand and waves gently toward the camera two or three times, smiling naturally, then lowers the hand. One continuous shot, smooth natural movement.","enabled":true},{"id":"heart","label":{"zh-CN":"比心","en":"Hand heart","ja":"ハートポーズ","ko":"손하트"},"emoji":"🫶","minLevel":2,"promptFragment":"The character brings both hands together at chest level to form a heart, holds it briefly with a warm smile, then relaxes the hands. Smooth continuous movement and consistent identity.","enabled":true},{"id":"turn","label":{"zh-CN":"转身","en":"Turn around","ja":"振り向く","ko":"뒤돌아보기"},"emoji":"💃","minLevel":1,"promptFragment":"The character slowly turns to the side, glances back over one shoulder toward the camera with a gentle smile, then comes to a natural stop. A continuous medium shot with smooth motion.","enabled":true},{"id":"nod","label":{"zh-CN":"点头微笑","en":"Nod and smile","ja":"うなずいて微笑む","ko":"끄덕이며 미소"},"emoji":"😊","minLevel":1,"promptFragment":"The character looks toward the camera, gives a small friendly nod and gradually breaks into a natural smile. Subtle breathing and blinking, a steady continuous shot.","enabled":true},{"id":"blow_kiss","label":{"zh-CN":"飞吻","en":"Blow a kiss","ja":"投げキッス","ko":"손키스"},"emoji":"😘","minLevel":3,"promptFragment":"The character lifts one hand to the lips and gently blows a kiss toward the camera, then lowers the hand with an affectionate smile. Natural facial movement in one continuous shot.","enabled":true},{"id":"twirl","label":{"zh-CN":"轻盈转圈","en":"Gentle twirl","ja":"軽く一回転","ko":"가볍게 돌기"},"emoji":"🌷","minLevel":4,"promptFragment":"The character takes a small step and makes one graceful slow twirl, allowing clothing and hair to follow the movement naturally, then faces the camera again. A stable full-body shot.","enabled":true},{"id":"dance","label":{"zh-CN":"轻快舞动","en":"Playful dance","ja":"軽やかに踊る","ko":"가볍게 춤추기"},"emoji":"🎵","minLevel":4,"promptFragment":"The character performs a short playful dance with two gentle side steps and relaxed arm movements, smiling with the rhythm. Continuous smooth full-body movement, steady framing.","enabled":true},{"id":"walk_together","label":{"zh-CN":"牵手同行","en":"Walk together","ja":"手をつないで歩く","ko":"손잡고 걷기"},"emoji":"🤝","minLevel":6,"promptFragment":"From a first-person viewpoint, the character reaches one hand toward the viewer as if inviting them to hold hands, then starts walking forward and glances back warmly. Gentle continuous tracking movement.","enabled":true},{"id":"good_night","label":{"zh-CN":"晚安挥手","en":"Goodnight wave","ja":"おやすみの手振り","ko":"잘 자 인사"},"emoji":"🌙","minLevel":7,"promptFragment":"In a quiet cozy evening setting, the character gives a small sleepy wave toward the camera, closes the eyes briefly with a soft smile, and relaxes. Gentle breathing and natural continuous movement.","enabled":true}]}' AS JSON))), revision = revision + 1, publishedRevision = publishedRevision + 1, publishedAt = CURRENT_TIMESTAMP WHERE JSON_EXTRACT(draft, '$.videos') IS NULL OR JSON_EXTRACT(published, '$.videos') IS NULL;
