UPDATE generationRequests SET videoTask = JSON_REMOVE(JSON_SET(videoTask, '$.input.presetId', COALESCE(JSON_EXTRACT(videoTask, '$.input.presetId'), JSON_EXTRACT(videoTask, '$.input.poseId'))), '$.input.poseId') WHERE kind = 'video' AND JSON_CONTAINS_PATH(videoTask, 'one', '$.input.poseId') = 1;
